def unique_customers(orders):
    seen = []
    result = []
    for order in orders:
        if order["customer"] not in seen:
            seen.append(order["customer"])
            result.append(order)
    return result


def unique_fast(orders):
    seen = set()
    result = []
    for order in orders:
        if order["customer"] not in seen:
            seen.add(order["customer"])
            result.append(order)
    return result


def render_csv(rows):
    text = ""
    for row in rows:
        text += ",".join(str(v) for v in row) + "\n"
    return text


def render_csv_fast(rows):
    lines = []
    for row in rows:
        lines.append(",".join(str(v) for v in row))
    return "\n".join(lines) + "\n"


def corner_pairs():
    pairs = []
    for a in range(3):
        for b in range(3):
            pairs.append((a, b))
    return pairs
